INSERT INTO `announcements` (`id`, `title`, `date`, `category`, `description`, `effective`, `status`) VALUES
  ('a-01', 'R5 Route Rerouting via National Highway', '2024-09-01 00:00:00', 'Rerouting', 'Route R5 (Bulua – Cogon) is temporarily rerouted due to ongoing road rehabilitation along the original path. Jeepneys will now travel via an alternative segment of National Highway.', 'September 1 – October 15, 2024', 'Active'),
  ('a-02', 'R8 Route Update: New Loading Points', '2024-09-10 00:00:00', 'Loading point change', 'Route R8 (Carmen – Agora) now has updated loading and unloading designations near Limketkai Center. Please refer to the updated stop list.', 'Effective September 10, 2024', 'Updated'),
  ('a-03', 'R10 Temporary Route: Patag – Cogon', '2024-09-05 00:00:00', 'Route update', 'Route R10 is operating on a temporary route alignment due to flooding affecting Masterson Ave. Service may be limited during heavy rains.', 'Until further notice', 'Temporary'),
  ('a-04', 'Terminal Consolidation at Cogon Market', '2024-08-20 00:00:00', 'Terminal change', 'Loading and unloading designations at Cogon Market Terminal have been reorganized. Multiple routes are affected. Please observe updated signage.', 'Effective August 20, 2024', 'Updated'),
  ('a-05', 'Expired Notice: Road Repairs at Gusa Rd', '2024-07-01 00:00:00', 'Road closure', 'Road repairs along Gusa Rd have been completed. Route R12 has resumed normal operations.', 'Ended July 20, 2024', 'Expired');
INSERT INTO `content_pages` (`slug`, `title`, `sections`) VALUES
  ('privacy', 'Privacy Policy', '[{"body":"OroRuta does not require account registration. We collect an anonymous device identifier (UUID) generated on your device to save your route history and preferences locally. We do not collect your name, email address, phone number, or any personally identifiable information.","heading":"Information We Collect"},{"body":"With your permission, OroRuta accesses your device GPS to show your current location on the map and provide step-by-step navigation assistance. Your location data is processed on-device and is not transmitted to our servers. We do not track jeepney positions.","heading":"Location Data"},{"body":"We collect anonymized search history (origin and destination pairs) associated with your device ID to improve route suggestions. This data does not identify you personally.","heading":"Usage Data"},{"body":"Search history and saved routes are stored on your device via the app database. You can clear this data at any time from the More screen.","heading":"Data Retention"},{"body":"OroRuta uses Google Maps SDK for Android for map tile rendering and location services. Google has its own privacy policy. We do not share your data with other third parties.","heading":"Third-Party Services"},{"body":"For privacy concerns, contact the research team at the College of Information Technology, Liceo de Cagayan University.","heading":"Contact"}]'),
  ('terms', 'Terms & Disclaimer', '[{"body":"All route information in OroRuta is based on sample research data derived from the Cagayan de Oro Land Public Transportation Route Plan (LPTRP). This data is provided for academic and informational purposes only.","heading":"Use of Information"},{"body":"Fare estimates shown in the app are calculated using the LTFRB minimum fare of ₱13.00 for the first 4 km and ₱1.80 per succeeding km. These are estimates only and may not reflect current LTFRB-approved fares. Always confirm fares with official sources.","heading":"Fare Estimates"},{"body":"Route alignments, stop locations, and terminal information are approximate and based on research data. Actual jeepney routes may vary. OroRuta is not responsible for inaccurate route information.","heading":"Route Accuracy"},{"body":"OroRuta does NOT track jeepney positions. GPS is used solely for the user\'s own location and navigation assistance.","heading":"No Jeepney Tracking"},{"body":"Reports submitted through the app are user-generated and have not been verified. They should not be treated as official information without proper verification.","heading":"User Reports"},{"body":"The developers of OroRuta shall not be liable for any damages arising from reliance on the information provided in this app. Use at your own discretion.","heading":"Limitation of Liability"},{"body":"OroRuta is developed as part of a BSIT research project at the College of Information Technology, Liceo de Cagayan University. It references the CDO LPTRP and aligns with UN SDG 9 (Industry, Innovation and Infrastructure), SDG 11 (Sustainable Cities and Communities), and SDG 13 (Climate Action).","heading":"Academic Research"}]');
